package io.aetheris.orchestrator.remote;import jakarta.transaction.Transactional;import org.springframework.stereotype.Service;import java.nio.charset.StandardCharsets;import java.security.*;import java.time.*;import java.util.*;@Service public class RemoteCompanionService {private final RemoteCompanionSessionRepository repository;public RemoteCompanionService(RemoteCompanionSessionRepository repository){this.repository=repository;}@Transactional public RemoteCompanionSessionResponse pair(Set<String> capabilities,int ttlMinutes){Set<String> caps=capabilities==null?Set.of("READ_STATUS"):Set.copyOf(capabilities);for(String c:caps)if(!Set.of("READ_STATUS","VIEW_NOTIFICATIONS","PAUSE_TASK","STOP_TASK","TAKE_CONTROL").contains(c))throw new IllegalArgumentException("Unsupported remote capability: "+c);String token=UUID.randomUUID()+"."+UUID.randomUUID();Instant expires=Instant.now().plus(Duration.ofMinutes(Math.max(5,Math.min(ttlMinutes,1440))));RemoteCompanionSessionEntity e=repository.save(new RemoteCompanionSessionEntity(UUID.randomUUID(),hash(token),caps,expires));return new RemoteCompanionSessionResponse(e.getId(),token,expires,caps,"AUTHENTICATED_PRIVATE_CHANNEL_CONTRACT");}public RemoteCompanionSessionEntity authenticate(UUID id,String token,String capability){RemoteCompanionSessionEntity e=repository.findById(id).orElseThrow(()->new NoSuchElementException("Unknown remote session"));if(e.isRevoked()||Instant.now().isAfter(e.getExpiresAt()))throw new IllegalStateException("Remote session is expired or revoked");if(!MessageDigest.isEqual(e.getTokenHash().getBytes(StandardCharsets.UTF_8),hash(token).getBytes(StandardCharsets.UTF_8)))throw new SecurityException("Invalid remote token");if(capability!=null&&!e.capabilities().contains(capability))throw new SecurityException("Capability not granted");return e;}@Transactional public void revoke(UUID id){RemoteCompanionSessionEntity e=repository.findById(id).orElseThrow();e.revoke();repository.save(e);}private String hash(String v){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(v.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}}
